<?php require '../includes/functions.php'; require_customer(); $user=current_customer(); $pageTitle='Customer Dashboard'; require '../includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['update_profile'])){$pdo->prepare('UPDATE users SET name=?,phone=?,address=? WHERE id=?')->execute([$_POST['name'],$_POST['phone'],$_POST['address'],$user['id']]);$_SESSION['flash']='Profile updated.';redirect('dashboard.php');}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['change_password'])){$pdo->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($_POST['new_password'],PASSWORD_DEFAULT),$user['id']]);$_SESSION['flash']='Password changed.';redirect('dashboard.php');}
if(isset($_GET['reorder'])){ $oid=(int)$_GET['reorder']; $rows=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$rows->execute([$oid]); foreach($rows->fetchAll() as $r) $_SESSION['cart'][uniqid('cart_',true)]=['product_id'=>$r['product_id'],'qty'=>$r['quantity'],'notes'=>$r['custom_notes']]; redirect('../cart.php'); }
$orders=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$orders->execute([$user['id']]);$orders=$orders->fetchAll(); ?>
<main class="section-pad"><div class="container"><div class="d-flex justify-content-between align-items-center mb-4"><h1 class="fw-bold">Customer Dashboard</h1><a href="logout.php" class="btn btn-outline-danger">Logout</a></div><div class="row g-4"><div class="col-lg-4"><div class="p-4 rounded-4 shadow-sm"><h4>Profile</h4><form method="post"><input name="name" class="form-control mb-2" value="<?= e($user['name']) ?>"><input name="phone" class="form-control mb-2" value="<?= e($user['phone']) ?>"><textarea name="address" class="form-control mb-2"><?= e($user['address']) ?></textarea><button name="update_profile" class="btn btn-yellow">Save Profile</button></form><hr><form method="post"><input name="new_password" type="password" minlength="6" class="form-control mb-2" placeholder="New password"><button name="change_password" class="btn btn-red">Change Password</button></form></div><div class="p-4 rounded-4 shadow-sm mt-3"><h4>Notifications</h4><?php $n=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 5');$n->execute([$user['id']]);foreach($n as $note): ?><p class="small border-bottom pb-2"><?= e($note['message']) ?></p><?php endforeach; ?></div></div><div class="col-lg-8"><h4>Order History and Tracking</h4><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th>Date</th><th>Total</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?= e($o['invoice_no']) ?></td><td><?= e($o['created_at']) ?></td><td><?= money($o['total_amount']) ?></td><td><?= status_badge($o['status']) ?></td><td><a class="btn btn-sm btn-red" href="../invoice.php?id=<?= $o['id'] ?>">Invoice</a> <a class="btn btn-sm btn-yellow" href="?reorder=<?= $o['id'] ?>">Reorder</a></td></tr><?php endforeach; ?></tbody></table></div><h4 class="mt-4">Uploaded Files</h4><ul class="list-group"><?php $files=$pdo->prepare('SELECT f.* FROM uploaded_files f JOIN orders o ON o.id=f.order_id WHERE o.user_id=? ORDER BY f.id DESC');$files->execute([$user['id']]);foreach($files as $f): ?><li class="list-group-item d-flex justify-content-between"><span><?= e($f['original_name']) ?> - <?= e($f['status']) ?></span><a href="../<?= e($f['file_path']) ?>" download>Download</a></li><?php endforeach; ?></ul></div></div></div></main><?php require '../includes/footer.php'; ?>